power.set:
enum apl_run_state state = apl_core_get_run_state(&self->core);
    if (value) return state == APL_RUN_ON || send_command(self, APL_LINK_CMD_POWER, 0u);
    if (state == APL_RUN_ON) return send_command(self, APL_LINK_CMD_POWER, 0u);
    return state == APL_RUN_STANDBY || state == APL_RUN_DRY;

purify.get:
struct apl_link_snapshot s;
    apl_core_get_snapshot(&self->core, &s);
    return s.purify_on != 0u;

purify.set:
struct apl_link_snapshot s;
    apl_core_get_snapshot(&self->core, &s);
    return (s.purify_on != 0u) == value || send_command(self, APL_LINK_CMD_PURIFY_TOGGLE, 0u);

